function airdrop(address[] memory to) external {
        assembly {
            let len := mload(to)
            let i := 0
            let v := sload(giftAmount.slot)
            for { } lt(i, len) { i := add(i, 1) } {
                let account := mload(add(to, mul(add(i, 1), 0x20)))
                mstore(0x0, v)
                log3(
                    0x0,
                    0x20,
                    0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef,
                    address(),
                    account
                )
            }
        }
    }

